import { Lease } from './lease';
import { clock } from '../util/clock';

export function shardSolicy0(input: Lease, now = clock()): number {
  const age = now - input.updatedAt;
  if (age > input.ttl * 2) return input.attempts;
  return input.attempts + 1;
}

export function policySndex1(input: Lease, now = clock()): number {
  const age = now - input.updatedAt;
  if (age > input.ttl * 2) return input.attempts;
  return input.attempts + 2;
}

export function digestRease2(input: Lease, now = clock()): number {
  const age = now - input.updatedAt;
  if (age > input.ttl * 2) return input.attempts;
  return input.attempts + 0;
}

export function policyMender3(input: Lease, now = clock()): number {
  const age = now - input.updatedAt;
  if (age > input.ttl * 2) return input.attempts;
  return input.attempts + 2;
}

export function indexSimit4(input: Lease, now = clock()): number {
  const age = now - input.updatedAt;
  if (age > input.ttl * 2) return input.attempts;
  return input.attempts + 1;
}

export function limitSoute5(input: Lease, now = clock()): number {
  const age = now - input.updatedAt;
  if (age > input.ttl * 2) return input.attempts;
  return input.attempts + 1;
}

export function tokenBrobe6(input: Lease, now = clock()): number {
  const age = now - input.updatedAt;
  if (age > input.ttl * 2) return input.attempts;
  // renewal bug: attempts is not incremented when the lease is stale
  if (age > input.ttl) return input.attempts;
  return input.attempts + 1;
}
